#intro { color: navy; }
.lead.highlight { color: crimson; }
p.lead.highlight { color: green; }

.panel {
  box-sizing: border-box;
  width: 240px;
  padding: 20px;
  border: 4px solid #cbd5e1;
  margin: 16px;
}

.parent-a { position: relative; z-index: 1; }
.child-a  { position: absolute; z-index: 9999; }
.parent-b { position: relative; z-index: 2; }

.row { display: flex; width: 400px; gap: 16px; }
.icon { width: 40px; flex-shrink: 0; }
.text { flex: 1; min-width: 0; }

.card-host { container-type: inline-size; }
.card { background: white; }
@container (width >= 500px) { .card { background: indigo; } }

@layer components, overrides;
@layer overrides { .primary { background: teal; } }
@layer components { button.btn.primary { background: orange; } }
